function cartReducer(state, action) {
  switch (action.type) {
    case "add": {
      const found = state.find((i) => i.id === action.item.id);
      if (found) return state.map((i) => (i.id === found.id ? { ...i, qty: i.qty + 1 } : i));
      return [...state, { ...action.item, qty: 1 }];
    }
    case "remove": return state.filter((i) => i.id !== action.id);
    default: return state;
  }
}

function assertEqual(actual, expected, name) {
  const ok = JSON.stringify(actual) === JSON.stringify(expected);
  console.log((ok ? "PASS" : "FAIL") + " - " + name);
}

assertEqual(cartReducer([], { type: "add", item: { id: 1, name: "Pen" } }), [{ id: 1, name: "Pen", qty: 1 }], "adds a new item");
assertEqual(
  cartReducer([{ id: 1, name: "Pen", qty: 1 }], { type: "add", item: { id: 1, name: "Pen" } }),
  [{ id: 1, name: "Pen", qty: 2 }],
  "increments quantity for an existing item"
);
assertEqual(cartReducer([{ id: 1, qty: 1 }], { type: "remove", id: 1 }), [], "removes an item");

