import { setupServer } from "msw/node";

export const server = setupServer(
  http.get("/api/users", () => HttpResponse.json([{ id: 1, name: "Asha" }, { id: 2, name: "Ravi" }]))
);

// UserList.test.jsx
import { render, screen } from "@testing-library/react";
import { http, HttpResponse } from "msw";
import { server } from "./test/server";
import { UserList } from "./UserList";

it("shows users from the API", async () => {
  render(<UserList />);
  expect(screen.getByText(/loading/i)).toBeInTheDocument();
  expect(await screen.findByText("Asha")).toBeInTheDocument();
  expect(screen.getByText("Ravi")).toBeInTheDocument();
});

it("shows an error when the API fails", async () => {
  server.use(http.get("/api/users", () => new HttpResponse(null, { status: 500 })));
  render(<UserList />);
  expect(await screen.findByRole("alert")).toHaveTextContent(/failed/i);
});

topics.description:
Component tests run in a fake DOM. **End-to-end (E2E) tests** open a real browser, visit your running app and click through flows like signing up or paying. They find integration problems nothing else does, but are slower and more brittle, so keep them few and focused on **critical paths**.

### Playwright

Made by Microsoft. Supports Chromium, Firefox and WebKit, parallel runs, auto-waiting, tracing (a time-travel viewer), codegen (`npx playwright codegen`), API testing and component testing. Written in TypeScript/JavaScript, Python, Java and .NET.

```js
test("user can add a todo", async ({ page }) => {
  await page.goto("/");
  await page.getByPlaceholder("What needs to be done?").fill("Buy milk");
  await page.keyboard.press("Enter");
  await expect(page.getByText("Buy milk")).toBeVisible();
});
```

### Cypress

Runs inside the browser with an interactive runner and great time-travel debugging, automatic retries and network stubbing (`cy.intercept`). Historically limited to Chromium/Firefox/Edge and single tab.

```js
it("adds a todo", () => {
  cy.visit("/");
  cy.findByPlaceholderText("What needs to be done?").type("Buy milk{enter}");
  cy.contains("Buy milk").should("be.visible");
});
```

### Choosing

| | Playwright | Cypress |
| --- | --- | --- |
| Browsers | Chromium, Firefox, WebKit | Chromium family, Firefox, WebKit (experimental) |
| Parallelism | built-in and free | paid cloud or CI splitting |
| Multi-tab / origin | supported | limited |
| DX | traces, codegen | interactive runner |

Both are good; Playwright is the more common choice for new projects.

### Best practices

Use user-facing locators (role, label, text), seed test data via API, mock third-party services, avoid fixed sleeps, and run E2E in CI on preview deployments.

