import { test, expect } from "@playwright/test";

test("shows products and handles server error", async ({ page }) => {
  await page.route("**/api/products", (route) =>
    route.fulfill({ json: [{ id: 1, name: "Keyboard" }] })
  );
  await page.goto("http://localhost:5173/products");
  await expect(page.getByRole("heading", { name: "Products" })).toBeVisible();
  await expect(page.getByText("Keyboard")).toBeVisible();

  await page.route("**/api/products", (route) => route.fulfill({ status: 500 }));
  await page.reload();
  await expect(page.getByRole("alert")).toContainText("Something went wrong");
});
